import{_ as i,l,o as e,c as s,v as t,p as n,x as o,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"隔离与沙箱","description":"","frontmatter":{"title":"隔离与沙箱","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/isolation-sandbox.md","filePath":"cs/isolation-sandbox.md","lastUpdated":1789023840000}'),h={name:"cs/isolation-sandbox.md"};function _(E,a,m,B,f,u){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="隔离与沙箱" tabindex="-1">隔离与沙箱 <a class="header-anchor" href="#隔离与沙箱" aria-label="Permalink to &quot;隔离与沙箱&quot;">​</a></h1><div class="epigraph"><p>把不可信代码放进权限更小的盒子：进程、虚拟机、seccomp 或语言运行时。盒子破了，损失应停在边界上。</p><footer>—— 据 Lampson 保护；Saltzer 完全中介；操作系统进程隔离的实践整理</footer></div><p><a href="/cs/cfi">上一课</a>在同一地址空间里加 NX 与随机化。本课不重讲页位。缺口是：越界与逻辑漏洞仍会发生，纵深要求<strong>缩小主体能碰的客体</strong>。<a href="/cs/kernel-user">内核与用户态</a>已把用户进程互相隔开；沙箱是更细的盒子：同一用户下再切，或把解析器、插件、渲染器丢掉大部分系统调用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进程隔离依赖内核引用监视器与各自页表。同一进程里的库没有这层边界。缺口不是再讲页表漫游，而是多层隔离：进程、容器（命名空间+cgroup）、虚拟机、基于语言的 WASM/JVM、系统调用过滤。每一层对应威胁模型里「逃逸之后还剩什么」。</p><p><span class="marginnote">沙箱不是加密。它服务 CIA 的 C/I/A 中「损坏半径」：密钥与主机文件系统尽量不进盒子。侧信道表明：共享硬件时，逻辑盒子仍可能漏。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>原则：不可信输入的处理者持最小能力集（对照<a href="/cs/capability-vs-acl">能力</a>）。浏览器多进程：渲染器无文件、无原始套接字。数据库 UDF、浏览器插件同构。本课不比较具体产品，只锁定：隔离 = 另一套页表或另一套系统调用策略 + 明确的数据通道。</p>',8)),(e(),n(c,null,{default:o(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20UNTRUST%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%A1%E4%BB%A3%E7%A0%81%22%5D%20--%3E%20BOX%5B%22%E6%9B%B4%E5%B0%8F%E6%9D%83%E9%99%90%E5%9F%9F%22%5D%0A%20%20BOX%20--%3E%20CH%5B%22%E6%98%BE%E5%BC%8F%E9%80%9A%E9%81%93%22%5D%0A%20%20BOX%20--%3E%20SC%5B%22%E5%90%8E%E8%AF%BE%3A%20%E4%BE%A7%E4%BF%A1%E9%81%93%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>隔离把保护矩阵的主体变细：不是「用户 www-data」，而是「渲染器实例 #12」。通道（管道、套接字、共享内存）必须再做认证与完整性，否则盒子外的信任会从通道流回去。这与<a href="/cs/two-pc">两阶段提交</a>的参与者隔离不同：那里假设参与者诚实但会崩溃；这里假设盒子内代码不诚实。</p><p>TCB 含内核与监视器。盒子再小，内核漏洞仍是公共逃逸面。缩小 TCB 是微内核对照，不插入本课。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>逻辑隔离不关共享缓存、时间、风扇噪声——下一课侧信道。也不要把容器当成虚拟机级的威胁模型。内核漏洞可以一次打穿所有进程盒子；那是 TCB 大小问题，不是「没开 ASLR」。</p><p>沙箱逃逸是「盒子的引用监视器被绕过」，与盒内越界是不同边界。后课默认：逻辑边界已尽量缩小；共享微结构仍可能泄漏密钥比特。</p><p>盒子的数据通道上仍要认证与完整性，否则隔离只是把敌手挪到管道对端。通道策略与盒子权限同样是矩阵的一部分。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>后课默认：逻辑盒子已尽量小，微结构泄漏另计。</p></li><li><p>容器与虚拟机的威胁模型不同：前者共享内核，后者多一层管理程序。</p></li><li><p>后课侧信道说明共享硬件时逻辑盒子仍可能漏密钥。</p></li><li><p>NX/ASLR 在盒内减可利用性；本课用更小权限域限制爆炸半径。</p></li><li><p>通道必须显式；沙箱不是加密。</p></li><li><p>共享硬件上的泄漏是侧信道课的缺口。</p></li><li><p>出处：Lampson；Saltzer and Schroeder；操作系统隔离实践。</p></li></ul>',9))])}const S=i(h,[["render",_]]);export{T as __pageData,S as default};
